function driveNotionFiles({ events }) {
  if (!Array.isArray(events)) throw new Error("Expected a Google Drive event batch");
  const seen = new Set();
  const files = events.map((event) => {
    if (
      !event ||
      event.eventType !== "file_created" ||
      event.itemType !== "file" ||
      typeof event.fileId !== "string" ||
      !event.fileId ||
      typeof event.name !== "string" ||
      typeof event.webViewLink !== "string" ||
      !/^https:\/\/[^\s/]+\//.test(event.webViewLink)
    )
      throw new Error("Expected a new file with its original HTTPS viewer link");
    if (seen.has(event.fileId)) throw new Error("Duplicate Google Drive file in this batch");
    seen.add(event.fileId);
    return { fileId: event.fileId, name: event.name, webViewLink: event.webViewLink };
  });
  return { files };
}

const items = $input.all();
const files = driveNotionFiles({
  events: items.map((item) => ({
    eventType: "file_created",
    itemType: "file",
    fileId: item.json.id,
    name: item.json.name,
    webViewLink: item.json.webViewLink,
  })),
}).files;
return [{ json: { files } }];

function driveNotionSchema({ dataSource }) {
  if (
    !dataSource ||
    dataSource.object !== "data_source" ||
    typeof dataSource.id !== "string" ||
    !dataSource.id ||
    dataSource.in_trash === true ||
    !dataSource.properties ||
    typeof dataSource.properties !== "object"
  )
    throw new Error("Expected the configured Notion data source");
  const titles = Object.entries(dataSource.properties).filter(
    ([, property]) => property?.type === "title",
  );
  if (titles.length !== 1 || dataSource.properties.File?.type !== "files")
    throw new Error("Notion needs one title property and a File property of type files");
  return { dataSourceId: dataSource.id, titleKey: titles[0][0] };
}

const schema = driveNotionSchema({ dataSource: $input.first().json });
return $("Validate the new-file links")
  .first()
  .json.files.map((file) => {
    const properties = {
      File: { files: [{ name: file.name, type: "external", external: { url: file.webViewLink } }] },
    };
    if (file.name !== "")
      properties[schema.titleKey] = { title: [{ type: "text", text: { content: file.name } }] };
    return {
      json: {
        fileId: file.fileId,
        parent: { type: "data_source_id", data_source_id: schema.dataSourceId },
        properties,
      },
      pairedItem: { item: 0 },
    };
  });

const requests = $("Prepare the Notion pages").all();
if (!Number.isInteger($runIndex) || $runIndex < 0 || $runIndex >= requests.length)
  throw new Error("Invalid single-file loop index");
const request = requests[$runIndex].json;
if (
  $json.object !== "page" ||
  typeof $json.id !== "string" ||
  !$json.id ||
  $json.parent?.data_source_id !== request.parent.data_source_id
)
  throw new Error(
    "Notion did not confirm the page in the selected data source; creation may already have occurred",
  );
return { json: { fileId: request.fileId, page: $json } };
